const f = $input.first().json;
const emails = (s) => String(s || '').split(/[,;\s]+/).map(x => x.trim()).filter(x => x.includes('@'));
let aud = f.audiences;
if (typeof aud === 'string') aud = aud.split(',');
aud = (aud || []).map(a => String(a).trim()).filter(Boolean);
return [{ json: {
  projectName: String(f.projectName || '').trim(),
  update: String(f.update || '').trim().slice(0, 30000),
  internalOnly: String(f.internalOnly || '').trim(),
  audiences: aud,
  wantExec: aud.includes('Executive'),
  wantTeam: aud.includes('Team'),
  wantClient: aud.includes('Client'),
  clientName: String(f.clientName || 'the client').trim() || 'the client',
  recipients: { Executive: emails(f.execTo), Team: emails(f.teamTo), Client: emails(f.clientTo) },
  approverEmail: f.approverEmail,
  pauseSeconds: f.pauseSeconds
} }];

// Email layout helpers: full width, left aligned, table-based so Outlook renders it consistently.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const F = 'font-family:Segoe UI,Arial,Helvetica,sans-serif;color:#1f2937;';
const T = (t, sub) => '<p style="' + F + 'margin:0 0 4px 0;font-size:20px;font-weight:700;line-height:1.3">' + t + '</p>' + (sub ? '<p style="' + F + 'margin:0 0 14px 0;font-size:13px;color:#6b7280">' + sub + '</p>' : '');
const H = (t) => '<p style="' + F + 'margin:20px 0 8px 0;font-size:15px;font-weight:700">' + t + '</p>';
const P = (t) => '<p style="' + F + 'margin:0 0 10px 0;font-size:14px;line-height:1.5">' + t + '</p>';
const UL = (a) => (a && a.length) ? '<ul style="' + F + 'margin:0 0 10px 0;padding:0 0 0 20px;font-size:14px;line-height:1.5">' + a.map(x => '<li style="margin:0 0 4px 0">' + esc(x) + '</li>').join('') + '</ul>' : P('<em>None</em>');
const CELL = F + 'border:1px solid #d1d5db;padding:6px 8px;text-align:left;vertical-align:top;font-size:13px;line-height:1.4;';
const TBL = (head, rows) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 10px 0">' + (head ? '<tr>' + head.map(h => '<th style="' + CELL + 'background:#f3f4f6;font-weight:700">' + h + '</th>').join('') + '</tr>' : '') + rows.map(r => '<tr>' + r.map(c => '<td style="' + CELL + '">' + c + '</td>').join('') + '</tr>').join('') + '</table>';
const BOX = (t, line, bg) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:0 0 12px 0"><tr><td style="' + F + 'background:' + bg + ';border-left:4px solid ' + line + ';padding:10px 12px;font-size:14px;line-height:1.5">' + t + '</td></tr></table>';
const PILL = (t, bg) => '<span style="background:' + bg + ';color:#ffffff;padding:2px 10px;border-radius:10px;font-weight:700;font-size:12px">' + t + '</span>';
const BTN = '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:16px 0"><tr><td style="background:#1f4e79;border-radius:4px"><a href="%%DECIDE_URL%%" style="' + F + 'display:inline-block;padding:11px 22px;color:#ffffff;font-size:14px;font-weight:700;text-decoration:none">Review and decide</a></td></tr></table>';
const NOTE = (t) => '<p style="' + F + 'margin:16px 0 0 0;font-size:12px;line-height:1.5;color:#6b7280">' + t + '</p>';
const WRAP = (inner) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse"><tr><td style="' + F + 'padding:0;text-align:left">' + inner + '</td></tr></table>';
const RAG = { Green: '#1e7e34', Amber: '#b26a00', Red: '#b00020' };
const v = $('Translator').first().json.output;
const chk = $input.first().json.output || {};
const inp = $('Prepare Input').first().json;
const issues = (chk.issues || []).concat((chk.factChanges || []).map(x => ({ audience: x.audience, problem: 'Fact check: ' + x.problem, quote: '' })));
const plural = (n) => n + ' flag' + (n > 1 ? 's' : '');
const card = (label, key, want) => {
  if (!want) return '';
  const x = v[key] || {};
  const to = inp.recipients[label] || [];
  const mine = issues.filter(i => String(i.audience).toLowerCase() === label.toLowerCase());
  return H(label + ' version ' + (mine.length ? '<span style="color:#b00020">(' + plural(mine.length) + ')</span>' : '<span style="color:#1e7e34">(no flags)</span>'))
    + P('<span style="font-size:13px;color:#6b7280">Draft to: ' + (to.length ? esc(to.join(', ')) : 'no recipients yet (add them in Outlook)') + '</span>')
    + BOX('<b>' + esc(x.subject) + '</b><br>' + esc(x.body).replace(/\n/g, '<br>'), '#9ca3af', '#f9fafb')
    + (mine.length ? UL(mine.map(i => i.problem + (i.quote ? ': "' + i.quote + '"' : ''))) : '');
};
const banner = issues.length
  ? BOX('<b>The leak checker raised ' + plural(issues.length) + '.</b> Read them before approving. If a flag is real, reject and resubmit with clearer internal-only notes.', '#b00020', '#fdecea')
  : BOX('Leak checker: no internal information in the client version and no fact changes.', '#1e7e34', '#e8f5e9');
const body = T(esc(inp.projectName) + ' update', 'For: ' + esc(inp.audiences.join(', ')))
  + banner + BTN
  + card('Executive', 'executive', inp.wantExec) + card('Team', 'team', inp.wantTeam) + card('Client', 'client', inp.wantClient)
  + BTN
  + NOTE('Nothing has been saved yet. Approve to save each version as an Outlook draft (never sent automatically). Reject to discard. Your decision and comment are saved in the audit log.');
return [{ json: { subject: '[Approval needed] ' + inp.projectName + ' update for ' + inp.audiences.join(', ') + (issues.length ? ' (' + plural(issues.length) + ')' : ''), html: WRAP(body), flags: issues.length } }];

const v = $('Translator').first().json.output;
const inp = $('Prepare Input').first().json;
const out = [];
if (inp.wantExec && v.executive && v.executive.body) out.push({ json: { audience: 'Executive', subject: v.executive.subject, body: v.executive.body, to: inp.recipients.Executive.join(',') } });
if (inp.wantTeam && v.team && v.team.body) out.push({ json: { audience: 'Team', subject: v.team.subject, body: v.team.body, to: inp.recipients.Team.join(',') } });
if (inp.wantClient && v.client && v.client.body) out.push({ json: { audience: 'Client', subject: v.client.subject, body: v.client.body, to: inp.recipients.Client.join(',') } });
return out;
